    return state.scheme + "://" + state.hostname +
      (state.port ? ":" + state.port : "");
  }

  function resolve(valueRaw, baseRaw) {
    const valueText = String(valueRaw || "").trim();

    if (/^https?:\/\//iu.test(valueText)) return valueText;
